import '@planes/ui-react/overlays.css';

export default function DataTableExample() {
  type Row={id:string;name:string;status:string;amount:number};
  const rows:Row[]=Array.from({length:31},(_,index)=>({id:String(index+1),name:'合成データ '+(index+1),status:index%2?'完了':'確認待ち',amount:(index+1)*10}));
  const columns=useMemo<DataTableColumn<Row>[]>(()=>[
    {key:'name',header:'名前',render:row=>row.name,sortable:true,filterable:true,getValue:row=>row.name,sticky:true},
    {key:'status',header:'状態',render:row=><Badge tone={row.status==='完了'?'success':'warning'}>{row.status}</Badge>,filterable:true,getValue:row=>row.status},
    {key:'amount',header:'数量',render:row=>row.amount,type:'number',sortable:true,getValue:row=>row.amount}
  ],[]);
  const [selected,setSelected]=useState<string[]>([]);
  return <><p>選択した行: {selected.length}</p><DataTable columns={columns} rows={rows} getRowKey={row=>row.id} ariaLabel="合成データ一覧" selectable onSelectionChange={(_,keys)=>setSelected(keys)} /></>;
}
