import '@planes/ui-react/styles.css';

// 普通のHTMLだけ。Library部品、class、専用wrapperを必要としません。
export function NativeHtmlExample() {
  return <article aria-label="通常HTMLの例">
    <h3>小さな読書ノート</h3>
    <p>合成の文書です。<a href="#native-html">文書へのリンク</a>と<code>識別子</code>を普通に書けます。</p>
    <blockquote><p>落ち着いた線と余白で、引用を示します。</p></blockquote>
    <ul><li>文字と色をそろえる</li><li>意味のあるHTMLを使う</li></ul>
    <table aria-label="通常HTMLの表"><thead><tr><th>見出し</th><th>内容</th></tr></thead><tbody><tr><td>文書</td><td>個別classは不要です</td></tr><tr><td>状態</td><td>準備ができました</td></tr></tbody></table>
    <form onSubmit={event=>event.preventDefault()}>
      <p><label>名前 <input name="name" placeholder="表示名" /></label></p>
      <p><label>分類 <select name="category"><option>読書</option><option>メモ</option></select></label></p>
      <p><label>メモ <textarea name="note" rows={3} /></label></p>
      <p><label><input type="checkbox" name="favorite" /> お気に入り</label></p>
      <button type="submit">保存</button> <button disabled>準備中</button>
    </form>
  </article>;
}
